def turn_right():
    turn_left()
    turn_left()
    turn_left()

def turn_around():
    turn_left()
    turn_left()

def clean_square():
    while beepers_present():
        pick_beeper()

def clean_row():
    clean_square()
    while front_is_clear():
        move()
        clean_square()

def go_back():
    turn_around()
    while front_is_clear():
        move()
    turn_around()

def main():
    clean_row()
    go_back()
    while left_is_clear():
        turn_left()
        move()
        turn_right()
        clean_row()
        go_back()
